import json
with open('evaluations.json') as f:
    data = json.load(f)
for d in data:
    print(f"Iter {d['iteration']}: score={d['target_dissimilarity']:.4f}")
    for r in d['recipe']:
        print(f"  {r['ingredient']}: {r['fraction']:.4f}")
    print()
