{"code": "
import json
with open('evaluations.json') as f:
    data = json.load(f)
# Summary sorted
sorted_data = sorted(data, key=lambda x: x['target_dissimilarity'])
for d in sorted_data:
    ings = {r['ingredient']: round(r['fraction'],3) for r in d['recipe']}
    print(f"Iter {d['iteration']}: score={d['target_dissimilarity']:.4f} | {ings}")
"}

